// Validate incoming quest generation request
const { playerId, questType, category, difficulty, options } = $input.first().json;

// Validate required fields
if (!playerId) {
  throw new Error('Player ID is required');
}

// Set default values
const requestData = {
  playerId,
  questType: questType || 'side_quest',
  category: category || 'combat',
  difficulty: difficulty || 3,
  options: options || {},
  timestamp: new Date().toISOString(),
  requestId: `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
};

// Add context analysis
requestData.contextAnalysis = {
  playerLevel: options.playerLevel || 1,
  playerClass: options.playerClass || 'warrior',
  preferences: options.preferences || {
    combat: 0.5,
    exploration: 0.5,
    social: 0.5,
    mystery: 0.5,
    crafting: 0.5
  },
  completionRate: options.completionRate || 0.8,
  recentPerformance: options.recentPerformance || 0.7
};

// Determine if AI generation should be used
const useAI = difficulty >= 4 || options.forceAI || Math.random() > 0.3;
requestData.useAI = useAI;

// Log the request
console.log(`Quest generation request: ${requestData.requestId} for player ${playerId}`);

return { json: requestData };

