parameters.functionCode:
// Process AI-generated quest content
const aiResponse = $input.first().json;
let questData;

try {
  // Parse AI response
  if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
    const content = aiResponse.choices[0].message.content;

    // Try to extract JSON from the response
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      questData = JSON.parse(jsonMatch[0]);
    } else {
      throw new Error('No valid JSON found in AI response');
    }
  } else {
    throw new Error('Invalid AI response format');
  }

  // Standardize quest structure
  const standardizedQuest = {
    id: `ai_quest_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    title: questData.title || 'Generated Quest',
    description: questData.description || 'A mysterious quest awaits.',
    type: questData.type || 'side_quest',
    category: questData.category || 'combat',
    difficulty: questData.difficulty || 3,
    levelRequirement: questData.levelRequirement || 1,

    // Story elements
    story: {
      introduction: questData.introduction || '',
      background: questData.background || '',
      climax: questData.climax || '',
      resolution: questData.resolution || ''
    },

    // Objectives
    objectives: (questData.objectives || []).map((obj, index) => ({
      id: `obj_${index + 1}`,
      title: obj.title || `Objective ${index + 1}`,
      description: obj.description || '',
      type: obj.type || 'kill',
      target: obj.target || 'enemy',
      current: 0,
      required: obj.required || 1,
      completed: false,
      optional: obj.optional || false,
      hidden: obj.hidden || false,
      rewards: obj.rewards || []
    })),

    // Rewards
    rewards: {
      base: (questData.rewards || []).map(reward => ({
        type: reward.type || 'experience',
        amount: reward.amount || 100,
        description: reward.description || ''
      })),
      bonus: [],
      choice: questData.choiceRewards || { enabled: false, options: [] }
    },

    // Metadata
    generatedBy: 'ai',
    aiGenerated: true,
    aiModel: $env.OPENAI_MODEL || 'gpt-4',
    aiConfidence: 0.8,
    source: 'ai',
    tags: ['ai-generated', questData.category || 'general'],

    // Branching support
    branching: {
      enabled: questData.branching || false,
      currentPath: null,
      completedPaths: [],
      availablePaths: questData.availablePaths || [],
      pathHistory: []
    },

    // State
    state: 'active',
    active: true,
    personalized: true
  };

  return { json: standardizedQuest };

} catch (error) {
  console.error('Error processing AI quest:', error);

  // Fallback to basic quest structure
  return {
    json: {
      id: `fallback_quest_${Date.now()}`,
      title: 'Mysterious Adventure',
      description: 'An unexpected journey awaits you.',
      type: 'side_quest',
      category: 'exploration',
      difficulty: 3,
      levelRequirement: 1,
      objectives: [{
        id: 'obj_1',
        title: 'Explore the Unknown',
        description: 'Discover what lies beyond the familiar paths.',
        type: 'explore',
        target: 'unknown_location',
        current: 0,
        required: 1,
        completed: false
      }],
      rewards: {
        base: [{
          type: 'experience',
          amount: 200,
          description: 'Experience for your adventures'
        }],
        bonus: [],
        choice: { enabled: false, options: [] }
      },
      generatedBy: 'fallback',
      aiGenerated: false,
      state: 'active',
      active: true
    }
  };
}

// Process template-generated quest
const templateResponse = $input.first().json;
const originalRequest = $node["Validate & Prepare Request"].json;

// Create standardized quest from template
const questFromTemplate = {
  id: `template_quest_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  title: templateResponse.title || `${originalRequest.category} Quest`,
  description: templateResponse.description || 'A quest generated from template.',
  type: originalRequest.questType,
  category: originalRequest.category,
  difficulty: originalRequest.difficulty,
  levelRequirement: templateResponse.levelRequirement || Math.max(1, originalRequest.contextAnalysis.playerLevel - 2),

  // Story elements from template
  story: templateResponse.story || {
    introduction: '',
    background: '',
    climax: '',
    resolution: ''
  },

  // Objectives from template
  objectives: (templateResponse.objectives || []).map((obj, index) => ({
    id: `obj_${index + 1}`,
    title: obj.title || `Objective ${index + 1}`,
    description: obj.description || '',
    type: obj.type || 'kill',
    target: obj.target || 'target',
    current: 0,
    required: obj.required || 1,
    completed: false,
    optional: obj.optional || false,
    hidden: obj.hidden || false,
    rewards: obj.rewards || []
  })),

  // Rewards from template
  rewards: templateResponse.rewards || {
    base: [{
      type: 'experience',
      amount: 100 * originalRequest.difficulty,
      description: 'Quest completion reward'
    }, {
      type: 'gold',
      amount: 50 * originalRequest.difficulty,
      description: 'Gold reward'
    }],
    bonus: [],
    choice: { enabled: false, options: [] }
  },

  // Metadata
  generatedBy: 'template',
  aiGenerated: false,
  source: 'template',
  template: templateResponse.template || 'default',
  tags: ['template-generated', originalRequest.category],

  // Branching support
  branching: {
    enabled: templateResponse.branching || false,
    currentPath: null,
    completedPaths: [],
    availablePaths: templateResponse.availablePaths || [],
    pathHistory: []
  },

  // State
  state: 'active',
  active: true,
  personalized: false
};

return { json: questFromTemplate };

// Prepare final response
const questData = $input.first().json;
const originalRequest = $node["Validate & Prepare Request"].json;

// Create success response
const response = {
  success: true,
  requestId: originalRequest.requestId,
  quest: {
    id: questData.id,
    title: questData.title,
    description: questData.description,
    type: questData.type,
    category: questData.category,
    difficulty: questData.difficulty,
    levelRequirement: questData.levelRequirement,
    objectives: questData.objectives,
    rewards: questData.rewards,
    generatedBy: questData.generatedBy,
    aiGenerated: questData.aiGenerated,
    estimatedTime: Math.round(questData.objectives.length * 15), // 15 minutes per objective
    tags: questData.tags
  },
  message: `Quest "${questData.title}" generated successfully`,
  timestamp: new Date().toISOString(),
  metadata: {
    generationMethod: questData.aiGenerated ? 'ai' : 'template',
    processingTime: Date.now() - new Date(originalRequest.timestamp).getTime(),
    personalized: questData.personalized
  }
};

// Log successful generation
console.log(`Quest generated successfully: ${questData.id} using ${questData.generatedBy}`);

// Trigger follow-up workflows if needed
if (questData.difficulty >= 5) {
  // Trigger high-difficulty quest notification
  console.log(`High difficulty quest generated: ${questData.id}`);
}

if (questData.aiGenerated) {
  // Log AI generation for analytics
  console.log(`AI quest generated for player ${originalRequest.playerId}`);
}

return { json: response };

