const originalRequest = $node["Validate & Prepare Request"].json;

const analyticsData = {
  event: 'quest_generated',
  timestamp: new Date().toISOString(),
  playerId: originalRequest.playerId,
  questId: questData.id,
  questType: questData.type,
  questCategory: questData.category,
  difficulty: questData.difficulty,
  generationMethod: questData.aiGenerated ? 'ai' : 'template',
  processingTime: Date.now() - new Date(originalRequest.timestamp).getTime(),
  personalized: questData.personalized,
  objectiveCount: questData.objectives.length,
  hasRewards: questData.rewards.base.length > 0,
  hasBranching: questData.branching.enabled,
  aiModel: questData.aiModel || null,
